-- Suppliers, events and tanks: one record each, linked.
--
-- 1. New columns and indexes (generated by prisma migrate diff).
-- 2. Clear ids that point at nothing, so the new foreign keys can be added (by hand).
-- 3. Foreign keys (generated).
-- 4. Backfill (by hand): copy per-supplier settings out of the Setting JSON into the
--    new columns, and key brews' placed orders by supplier id.
--
-- Nothing is deleted. The Setting rows ordering.supplierPrefs, ordering.cutoffs and
-- brewery.supplierLeadRefs stay as they are (the app stops reading them). A value is only
-- written where the new column still holds its default, so nothing hand-set is overwritten
-- and running this again changes nothing. Broken JSON in a Setting skips that step with a
-- warning instead of failing the deploy.

-- ---- 1. Columns and indexes (generated) ------------------------------------------------

-- AlterTable
ALTER TABLE "Supplier" ADD COLUMN     "autoDraft" BOOLEAN NOT NULL DEFAULT true,
ADD COLUMN     "brewLeadDays" INTEGER,
ADD COLUMN     "brewLeadRef" TEXT,
ADD COLUMN     "cutoffDaysBefore" INTEGER,
ADD COLUMN     "cutoffPerDay" JSONB,
ADD COLUMN     "cutoffTime" TEXT,
ADD COLUMN     "orderAlert" TEXT,
ADD COLUMN     "orderFirst" TEXT NOT NULL DEFAULT '4h',
ADD COLUMN     "orderLastCallMins" INTEGER DEFAULT 60,
ADD COLUMN     "orderPeople" TEXT[] DEFAULT ARRAY[]::TEXT[],
ADD COLUMN     "orderPhone" TEXT,
ADD COLUMN     "orderRecipients" TEXT NOT NULL DEFAULT 'managers',
ADD COLUMN     "portalName" TEXT,
ADD COLUMN     "portalUrl" TEXT,
ADD COLUMN     "sendBy" TEXT NOT NULL DEFAULT 'email';

-- AlterTable
ALTER TABLE "Equipment" ADD COLUMN     "tankId" TEXT;

-- CreateIndex
CREATE INDEX "PrivateEvent_ownerId_idx" ON "PrivateEvent"("ownerId");

-- CreateIndex
CREATE INDEX "WebInquiry_privateEventId_idx" ON "WebInquiry"("privateEventId");

-- CreateIndex
CREATE UNIQUE INDEX "Equipment_tankId_key" ON "Equipment"("tankId");

-- ---- 2. Ids that point at nothing (by hand) ---------------------------------------------
-- Only an id whose row no longer exists is cleared; every id that still points at a row is kept.

UPDATE "PrivateEvent" pe SET "ownerId" = NULL
WHERE pe."ownerId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "User" u WHERE u."id" = pe."ownerId");

UPDATE "PrivateEvent" pe SET "calendarEventId" = NULL
WHERE pe."calendarEventId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "Event" e WHERE e."id" = pe."calendarEventId");

UPDATE "WebInquiry" w SET "privateEventId" = NULL
WHERE w."privateEventId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "PrivateEvent" pe WHERE pe."id" = w."privateEventId");

UPDATE "WebConversion" w SET "privateEventId" = NULL
WHERE w."privateEventId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "PrivateEvent" pe WHERE pe."id" = w."privateEventId");

-- ---- 3. Foreign keys (generated) ---------------------------------------------------------

-- AddForeignKey
ALTER TABLE "PrivateEvent" ADD CONSTRAINT "PrivateEvent_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "PrivateEvent" ADD CONSTRAINT "PrivateEvent_calendarEventId_fkey" FOREIGN KEY ("calendarEventId") REFERENCES "Event"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "WebInquiry" ADD CONSTRAINT "WebInquiry_privateEventId_fkey" FOREIGN KEY ("privateEventId") REFERENCES "PrivateEvent"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "WebConversion" ADD CONSTRAINT "WebConversion_privateEventId_fkey" FOREIGN KEY ("privateEventId") REFERENCES "PrivateEvent"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "Equipment" ADD CONSTRAINT "Equipment_tankId_fkey" FOREIGN KEY ("tankId") REFERENCES "Tank"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- ---- 4. Backfill (by hand) ----------------------------------------------------------------

-- 4a. Reminder and "send orders by" settings: Setting ordering.supplierPrefs
--     ({ "<supplier id>": { alert, first, lastCallMins, recipients, people, sendBy, phone, portal, portalUrl } })
--     into the supplier's own columns. Values are checked the way the app read them
--     (src/domain/supplierPrefs.ts parseSupplierPrefs); anything it would have ignored stays at the default.
--     Only suppliers that exist, and only while every one of these columns is still at its default.
DO $$
DECLARE prefs jsonb;
BEGIN
  SELECT "value"::jsonb INTO prefs FROM "Setting" WHERE "key" = 'ordering.supplierPrefs';
  IF prefs IS NULL OR jsonb_typeof(prefs) <> 'object' THEN RETURN; END IF;
  UPDATE "Supplier" s SET
    "orderAlert" = CASE WHEN p.v->>'alert' IN ('on', 'low', 'off') THEN p.v->>'alert' END,
    "orderFirst" = CASE WHEN p.v->>'first' IN ('24h', '4h', 'morning', 'none') THEN p.v->>'first' ELSE '4h' END,
    "orderLastCallMins" = CASE
      WHEN jsonb_typeof(p.v->'lastCallMins') = 'null' THEN NULL
      WHEN jsonb_typeof(p.v->'lastCallMins') = 'number' AND (p.v->>'lastCallMins') ~ '^[0-9]{1,4}$'
           AND (p.v->>'lastCallMins')::int BETWEEN 1 AND 1440 THEN (p.v->>'lastCallMins')::int
      ELSE 60 END,
    "orderRecipients" = CASE WHEN p.v->>'recipients' IN ('managers', 'people', 'shift') THEN p.v->>'recipients' ELSE 'managers' END,
    "orderPeople" = (
      SELECT COALESCE(array_agg(q.x ORDER BY q.i), ARRAY[]::text[])
      FROM (
        SELECT el #>> '{}' AS x, i
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p.v->'people') = 'array' THEN p.v->'people' ELSE '[]'::jsonb END) WITH ORDINALITY AS t(el, i)
        WHERE jsonb_typeof(el) = 'string' AND length(el #>> '{}') BETWEEN 1 AND 40
        ORDER BY i
        LIMIT 30
      ) q
    ),
    "sendBy" = CASE WHEN p.v->>'sendBy' IN ('email', 'text', 'portal', 'phone') THEN p.v->>'sendBy' ELSE 'email' END,
    "orderPhone" = CASE WHEN jsonb_typeof(p.v->'phone') = 'string' THEN NULLIF(left(btrim(p.v->>'phone', E' \t\r\n'), 40), '') END,
    "portalName" = CASE WHEN jsonb_typeof(p.v->'portal') = 'string' THEN NULLIF(left(btrim(p.v->>'portal', E' \t\r\n'), 60), '') END,
    "portalUrl" = CASE WHEN jsonb_typeof(p.v->'portalUrl') = 'string' AND left(btrim(p.v->>'portalUrl', E' \t\r\n'), 300) ~* '^https?://'
                       THEN left(btrim(p.v->>'portalUrl', E' \t\r\n'), 300) END
  FROM jsonb_each(prefs) AS p(id, v)
  WHERE s."id" = p.id
    AND jsonb_typeof(p.v) = 'object'
    AND s."orderAlert" IS NULL AND s."orderFirst" = '4h' AND s."orderLastCallMins" IS NOT DISTINCT FROM 60
    AND s."orderRecipients" = 'managers' AND COALESCE(cardinality(s."orderPeople"), 0) = 0
    AND s."sendBy" = 'email' AND s."orderPhone" IS NULL AND s."portalName" IS NULL AND s."portalUrl" IS NULL;
EXCEPTION WHEN others THEN
  RAISE WARNING 'ordering.supplierPrefs was not copied (%). The Setting row is untouched.', SQLERRM;
END $$;

-- 4b. Order deadlines: Setting ordering.cutoffs ({ "<supplier id>": { time, daysBefore, autoDraft, perDay } })
--     into cutoffTime / cutoffDaysBefore / autoDraft / cutoffPerDay. A saved daysBefore equal to the
--     supplier's lead time is not copied: the deadline then follows the lead time (the one number).
--     Only suppliers that exist, and only while all four columns are still at their defaults.
DO $$
DECLARE cut jsonb;
BEGIN
  SELECT "value"::jsonb INTO cut FROM "Setting" WHERE "key" = 'ordering.cutoffs';
  IF cut IS NULL OR jsonb_typeof(cut) <> 'object' THEN RETURN; END IF;
  UPDATE "Supplier" s SET
    "cutoffTime" = CASE WHEN jsonb_typeof(c.v->'time') = 'string' AND (c.v->>'time') ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN c.v->>'time' END,
    "cutoffDaysBefore" = CASE WHEN jsonb_typeof(c.v->'daysBefore') = 'number' AND (c.v->>'daysBefore') ~ '^[0-9]{1,3}$'
                              AND (c.v->>'daysBefore')::int <> s."leadTimeDays" THEN (c.v->>'daysBefore')::int END,
    "autoDraft" = NOT COALESCE(c.v->'autoDraft' = 'false'::jsonb, false),
    "cutoffPerDay" = CASE WHEN jsonb_typeof(c.v->'perDay') = 'object' AND c.v->'perDay' <> '{}'::jsonb THEN c.v->'perDay' END
  FROM jsonb_each(cut) AS c(id, v)
  WHERE s."id" = c.id
    AND jsonb_typeof(c.v) = 'object'
    AND s."cutoffTime" IS NULL AND s."cutoffDaysBefore" IS NULL AND s."autoDraft" = true AND s."cutoffPerDay" IS NULL;
EXCEPTION WHEN others THEN
  RAISE WARNING 'ordering.cutoffs was not copied (%). The Setting row is untouched.', SQLERRM;
END $$;

-- 4c. What a brewery supplier's lead time counts back from: Setting brewery.supplierLeadRefs
--     ({ "<supplier id>": "brew" | "dryHop" | "pkg" }) into brewLeadRef, where it is still empty.
DO $$
DECLARE refs jsonb;
BEGIN
  SELECT "value"::jsonb INTO refs FROM "Setting" WHERE "key" = 'brewery.supplierLeadRefs';
  IF refs IS NULL OR jsonb_typeof(refs) <> 'object' THEN RETURN; END IF;
  UPDATE "Supplier" s SET "brewLeadRef" = r.v #>> '{}'
  FROM jsonb_each(refs) AS r(id, v)
  WHERE s."id" = r.id
    AND s."brewLeadRef" IS NULL
    AND jsonb_typeof(r.v) = 'string'
    AND (r.v #>> '{}') IN ('brew', 'dryHop', 'pkg');
EXCEPTION WHEN others THEN
  RAISE WARNING 'brewery.supplierLeadRefs was not copied (%). The Setting row is untouched.', SQLERRM;
END $$;

-- 4d. Brewery suppliers' lead days: until now the brewery kept them in leadTimeDays. Copy them
--     to brewLeadDays where it is still empty; leadTimeDays itself is left exactly as it is.
UPDATE "Supplier" SET "brewLeadDays" = "leadTimeDays"
WHERE "department" = 'brewery' AND "brewLeadDays" IS NULL;

-- 4e. Placed orders on a brew were kept by supplier NAME ({ "Hudson Valley Malt": "2026-11-10" }).
--     Re-key each entry by the supplier's id when its name matches a supplier exactly (Supplier.name
--     is unique, so a match is always exactly one). A name that matches no supplier stays under its
--     name. If a brew already has the id key too, the id key's date wins. Only brews with at least
--     one name to change are touched, so a second run changes nothing.
UPDATE "BrewBatch" b
SET "ordered" = x.obj
FROM (
  SELECT bb."id",
         jsonb_object_agg(COALESCE(sup."id", e.key), e.value ORDER BY (sup."id" IS NULL), e.key) AS obj
  FROM "BrewBatch" bb
  CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(bb."ordered") = 'object' THEN bb."ordered" ELSE '{}'::jsonb END) AS e(key, value)
  LEFT JOIN "Supplier" sup ON sup."name" = e.key
  WHERE bb."ordered" IS NOT NULL AND jsonb_typeof(bb."ordered") = 'object'
  GROUP BY bb."id"
  HAVING bool_or(sup."id" IS NOT NULL)
) x
WHERE b."id" = x."id";
